import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        # Can't move anywhere if step length is zero and d != 0
        return float('inf')
    if length >= d:
        return 1
    # If the distance is less than 2*length, two jumps suffice due to any direction allowed
    if d <= 2 * length:
        return 2
    # Otherwise, compute the minimal number of jumps needed
    return math.ceil(d / length)

