def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift = shift % n
    if shift == 0:
        return s
    # positive shift means circular shift to the right
    return s[-shift:] + s[:-shift]

