def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()  # split by spaces, if none, single group
    # If input is empty string, split() returns [], but we want [0] as per clarification
    if not groups:
        return [0]
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

