def anti_shuffle(s):
    import re
    # Split into tokens of either spaces or non-space sequences
    tokens = re.findall(r'\S+|\s+', s)

    result = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Sort the characters of the word (including punctuation attached)
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)

    return ''.join(result)

